function simulateWork() {
  // 1. We allocate memory (Get a hotel room)
  let massiveData = new Array(10000).fill("Heavy Data");

  console.log("Processing data...");
  // Do something with massiveData...

  // 2. Function ends.
  // 'massiveData' is scoped to this function. 
  // Once the function returns, there is NO WAY to access it anymore.
}

simulateWork();

// 3. THE GARBAGE COLLECTOR ARRIVES
// The GC sees that 'massiveData' is completely unreachable from the main script.
// It safely sweeps it away, freeing up the RAM.

console.log("Variables scoped inside functions are naturally garbage collected. Global variables are NOT.");
